import re
import os

def normalize_yield(value_str):
    """Convert yield string like '6 80' or '6.80' to float."""
    if not value_str:
        return None
    # Replace spaces with dots and clean up
    value_str = value_str.strip().replace(' ', '.')
    try:
        return float(value_str)
    except:
        return None

def extract_yields_from_file_v2(filepath, target_year):
    """Extract 10-year constant maturity yields from a Treasury Bulletin file.
    Handles different column formats."""
    with open(filepath, 'r') as f:
        content = f.read()

    # Find the MY-1 table section
    my1_match = re.search(r'TABLE MY-1\.\-\-.*?TABLE MY-2', content, re.DOTALL)
    if not my1_match:
        return []

    table_content = my1_match.group()

    # Find header row to determine column positions
    # Try different column header formats
    header_patterns = [
        r'\|[^|]*10[- ]?yr[^|]*\|',  # 10-yr. or 10-yr (8)
    ]

    col_idx = None
    for pattern in header_patterns:
        header_match = re.search(pattern, table_content, re.IGNORECASE)
        if header_match:
            header_start = header_match.start()
            header_section = table_content[:header_start]
            col_idx = header_section.count('|')
            break

    if col_idx is None:
        return []

    # Split into lines and find the section we need
    lines = table_content.split('\n')

    yields = []
    current_year = None

    for line in lines:
        # Skip "End of month" rows - we stop after we see them
        if 'End of month' in line:
            break

        # Check for year marker like "1993 -"
        year_match = re.search(r'(\d{4})\s*-', line)
        if year_match:
            current_year = year_match.group(1)

        # Now look for month data in the monthly average section
        month_match = re.search(r'\|\s*(\d{4}\s*-)?\s*(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\.?\s*\|', line)

        if month_match and current_year == str(target_year):
            # Extract the 10-year yield
            parts = [p.strip() for p in line.split('|')]
            if len(parts) > col_idx:
                yield_10yr = normalize_yield(parts[col_idx])
                if yield_10yr is not None:
                    month = month_match.group(2)
                    yields.append((month, yield_10yr))

    return yields

# Get all files for each year
def get_year_data(year):
    """Get all yields for a given year from all relevant files."""
    all_yields = {}

    # For each quarter, check all files
    quarters = ['03', '06', '09', '12']
    for q in quarters:
        fpath = f'/app/corpus/treasury_bulletin_{year}_{q}.txt'
        if os.path.exists(fpath):
            yields = extract_yields_from_file_v2(fpath, year)
            for month, yield_val in yields:
                if month not in all_yields:
                    all_yields[month] = yield_val

    return all_yields

# Extract for each year
for year in [1993, 1998, 2003]:
    data = get_year_data(year)
    print(f"\n=== {year} DATA ===")
    # Sort by month order
    month_order = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
    for m in month_order:
        if m in data:
            print(f"  {m}: {data[m]}")
